"""Command-line framework: registry, argument reading, context, output rules."""
import os
import re
from datetime import date

from tallybook.dates import parse_date
from tallybook.errors import ConflictError, TallybookError


class UsageError(Exception):
    """The command line itself is wrong: exit status 2."""


class CliError(Exception):
    """The program refused: exit status 1, ``tallybook: message`` on stderr."""

    def __init__(self, message, lines=()):
        Exception.__init__(self, message)
        self.message = message
        self.lines = list(lines)


class Opt:
    """kind: 'value' (one value), 'flag' (no value) or 'repeat' (value, may repeat)."""

    def __init__(self, name, kind="value", required=False, short=None, metavar=None):
        self.name = name
        self.kind = kind
        self.required = required
        self.short = short
        self.metavar = metavar or name.upper()


class Cmd:
    """pos: list of (NAME, kind); kind '1' one, '?' optional, '*' any number, '+' at least one."""

    def __init__(self, words, usage, summary, handler, opts=(), pos=(), needs_book=True):
        self.words = tuple(words)
        self.usage = usage
        self.summary = summary
        self.handler = handler
        self.opts = {o.name: o for o in opts}
        self.shorts = {o.short: o for o in opts if o.short}
        self.pos = list(pos)
        self.needs_book = needs_book


class Node:
    def __init__(self):
        self.children = {}
        self.cmd = None
        self.summary = ""


ROOT = Node()


def command(words, usage, summary, opts=(), pos=(), needs_book=True):
    """Decorator: register ``handler(ctx, args)``; ``words`` like 'tx add'."""

    def register(handler):
        parts = words.split()
        node = ROOT
        for w in parts:
            node = node.children.setdefault(w, Node())
        node.cmd = Cmd(parts, usage, summary, handler, opts, pos, needs_book)
        return handler

    return register


def group_summary(words, summary):
    node = ROOT
    for w in words.split():
        node = node.children.setdefault(w, Node())
    node.summary = summary


class Args:
    def __init__(self, pos, opts):
        self.pos = pos
        self.opts = opts

    def get(self, name, default=None):
        value = self.opts.get(name)
        return default if value is None else value

    def flag(self, name):
        return bool(self.opts.get(name))

    def many(self, name):
        return list(self.opts.get(name) or [])


class HelpRequest(Exception):
    pass


def parse_args(cmd, tokens):
    pos = []
    values = {}
    ddash = False
    i = 0
    while i < len(tokens):
        tok = tokens[i]
        i += 1
        if ddash:
            pos.append(tok)
        elif tok == "--":
            ddash = True
        elif tok in ("-h", "--help"):
            raise HelpRequest()
        elif tok.startswith("--"):
            name, eq, val = tok[2:].partition("=")
            opt = cmd.opts.get(name)
            if opt is None:
                raise UsageError("unknown option: --%s" % name)
            if opt.kind == "flag":
                if eq:
                    raise UsageError("option --%s takes no value" % name)
                if name in values:
                    raise UsageError("option --%s given twice" % name)
                values[name] = True
                continue
            if not eq:
                if i >= len(tokens):
                    raise UsageError("option --%s needs a value" % name)
                val = tokens[i]
                i += 1
            _store(values, opt, val)
        elif tok in cmd.shorts and len(tok) == 2:
            opt = cmd.shorts[tok]
            if i >= len(tokens):
                raise UsageError("option --%s needs a value" % opt.name)
            val = tokens[i]
            i += 1
            _store(values, opt, val)
        else:
            pos.append(tok)
    for opt in cmd.opts.values():
        if opt.required and opt.name not in values:
            raise UsageError("missing required option --%s" % opt.name)
    need = sum(1 for _, k in cmd.pos if k in ("1", "+"))
    maximum = None if any(k in ("*", "+") for _, k in cmd.pos) else len(cmd.pos)
    if len(pos) < need:
        missing = [n for n, k in cmd.pos if k in ("1", "+")][len(pos)]
        raise UsageError("missing argument %s" % missing)
    if maximum is not None and len(pos) > maximum:
        raise UsageError("unexpected argument: %s" % pos[maximum])
    return Args(pos, values)


def _store(values, opt, val):
    if opt.kind == "repeat":
        values.setdefault(opt.name, []).append(val)
    else:
        if opt.name in values:
            raise UsageError("option --%s given twice" % opt.name)
        values[opt.name] = val


_INT = re.compile(r"-?[0-9]{1,18}")


def parse_int(text, what="number", negative=False):
    """A whole number argument: decimal digits, at most 18, optional '-' where allowed."""
    if not isinstance(text, str) or not _INT.fullmatch(text) or (text[0] == "-" and not negative):
        raise CliError("invalid %s '%s': expected a whole number" % (what, text))
    return int(text)


def parse_day(text, what="date"):
    return parse_date(text)


class Context:
    def __init__(self, db_path, today, stdin=None):
        self.db_path = db_path
        self._today = today
        self._stores = []
        self.stdin = stdin

    @property
    def today(self):
        return self._today if self._today is not None else date.today()

    def open_book(self, create=False, allow_old=False):
        from tallybook.storage import LATEST_VERSION, Store

        path = self.db_path
        if not create and not os.path.exists(path):
            raise CliError("no such database: %s (run `tallybook init`)" % path)
        store = Store.open(path, create=create)
        self._stores.append(store)
        if not allow_old and store.version < LATEST_VERSION:
            raise ConflictError("database is at version %d, run `tallybook db migrate`" % store.version)
        return store

    def close(self):
        for s in self._stores:
            try:
                s.close()
            except Exception:
                pass
        self._stores = []

    def read_input(self, path):
        """Text of a file, or standard input for '-'. Bytes are decoded as UTF-8 exactly."""
        import sys

        if path == "-":
            stream = self.stdin if self.stdin is not None else sys.stdin
            buf = getattr(stream, "buffer", None)
            try:
                raw = buf.read() if buf is not None else stream.read()
            except (OSError, ValueError) as err:
                raise CliError("cannot read standard input: %s" % err)
            label = "standard input"
        else:
            label = path
            try:
                with open(path, "rb") as fh:
                    raw = fh.read()
            except OSError as err:
                raise CliError("cannot read %s: %s" % (path, err.strerror or err))
        if isinstance(raw, str):
            return raw
        try:
            return raw.decode("utf-8")
        except UnicodeDecodeError:
            raise CliError("%s is not valid UTF-8 text" % label)


def input_label(path):
    return "standard input" if path == "-" else path


def wrap_input_errors(path, func, *args):
    """Run a parser on a file's text; prefix its message with the file name."""
    try:
        return func(*args)
    except TallybookError as err:
        raise CliError("%s: %s" % (input_label(path), err.message))
"""Helpers for the book command tests: run a command line, temp books, files."""
import contextlib
import io
import os
import shutil
import sys
import tempfile
import unittest

from tallybook.cli import main as cli_main
from tallybook.storage import Store


def _book_only():
    from tallybook.cli import book_commands  # noqa: F401


try:  # when the other command modules exist, run the real thing
    from tallybook.cli import book_commands, calc_commands, data_commands  # noqa: F401
except ImportError:
    cli_main._load_commands = _book_only


def run(argv, stdin=None):
    """Run ``main(argv)``; ``stdin`` is bytes or text. Returns (status, stdout, stderr)."""
    out, err = io.StringIO(), io.StringIO()
    old = sys.stdin
    if stdin is not None:
        raw = stdin if isinstance(stdin, bytes) else stdin.encode("utf-8")
        sys.stdin = io.TextIOWrapper(io.BytesIO(raw), encoding="utf-8", errors="surrogateescape")
    try:
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            status = cli_main.main(list(argv))
    finally:
        sys.stdin = old
    return status, out.getvalue(), err.getvalue()


class BookCase(unittest.TestCase):
    """A temp directory per test, a book path and helpers to run commands against it."""

    def setUp(self):
        self.dir = tempfile.mkdtemp(prefix="tbbook")
        self.addCleanup(shutil.rmtree, self.dir, True)
        self.db = os.path.join(self.dir, "book.db")
        saved = os.environ.pop("TALLYBOOK_DB", None)
        if saved is not None:
            self.addCleanup(os.environ.__setitem__, "TALLYBOOK_DB", saved)

    def path(self, name):
        return os.path.join(self.dir, name)

    def write(self, name, content):
        """Write a file once, in full (text as UTF-8 without translation, or bytes)."""
        full = self.path(name)
        data = content if isinstance(content, bytes) else content.encode("utf-8")
        with open(full, "wb") as fh:
            fh.write(data)
        return full

